#!/usr/bin/env node
// Reads SYNTHETIC scratch windows generated by verify-postgres.py only.
import {readFile} from 'node:fs/promises';
import {resolve,sep} from 'node:path';
import {randomBytes} from 'node:crypto';
import assert from 'node:assert/strict';
import {createSourceExportPreparer} from '../../scripts/lib/v2-source-export.mjs';
import {restoreChain} from '../../scripts/lib/v2-backup-core.mjs';
try{
  if(process.argv.length!==3)throw Error();const path=resolve(process.argv[2]);if(!path.split(sep).includes('.arena'))throw Error();
  const fixture=JSON.parse(await readFile(path,'utf8'));
  const source={project:'synthetic-source',clinicId:'00000000-0000-0000-0000-000000000001',schema:22,streamId:'fixture-stream-v1'};
  assert.deepEqual(fixture.baseline.source,source);assert.deepEqual(fixture.increment.source,source);assert.ok(Object.values(fixture.checks).every(v=>v===true));
  const tables=[{name:'patients',keyColumns:['id'],scopeColumn:'clinic_id'},{name:'appointments',keyColumns:['id'],scopeColumn:'clinic_id'},{name:'staff_branches',keyColumns:['staff_id','branch_id'],scopeColumn:'clinic_id'}];
  const key=randomBytes(32),options={key,keyId:'ephemeral-data-key',createdAt:'2026-01-01T00:00:00.000Z'};
  const prepare=window=>createSourceExportPreparer({source,tables,readWindow:async()=>window});
  const baseline=await prepare(fixture.baseline)({...options,batchId:'postgres-baseline'});
  const increment=await prepare(fixture.increment)({...options,batchId:'postgres-increment',previousDigest:baseline.entry.digest,low:baseline.watermark});
  assert.equal(baseline.status,'READY');assert.equal(increment.status,'READY');
  const restored=restoreChain({batches:[baseline.entry,increment.entry],keys:new Map([['ephemeral-data-key',key]]),project:source.project,schema:22,targetDigest:increment.entry.digest});
  const canonical=v=>JSON.stringify(v,(_,x)=>x&&Object.getPrototypeOf(x)===Object.prototype?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x);
  const counts={};
  for(const {name} of tables){const data=restored.tables[name].map(r=>r.data);assert.deepEqual(data.map(canonical).sort(),fixture.expected[name].map(canonical).sort());assert.ok(data.every(r=>r.clinic_id===source.clinicId));counts[name]=data.length;}
  assert.equal(restored.watermark,fixture.increment.high);assert.ok(!increment.entry.object.includes('FINAL_SYNTHETIC_ONE'));
  console.log(JSON.stringify({mode:'SYNTHETIC_POSTGRES_ENCRYPTED_REPLAY',ok:true,runtime:process.version,postgresChecksPassed:Object.keys(fixture.checks).length,baselineWatermark:baseline.watermark,restoredWatermark:restored.watermark,committedTransactionsReplayed:fixture.increment.transactions.length,restoredTableCounts:counts,clinicalConnections:0,note:'In-memory replay of local PostgreSQL fixture only. Not clinical export deployment, actual DB restore or RPO proof.'},null,2));
}catch{console.error('SYNTHETIC_SOURCE_REPLAY_FAILED');process.exitCode=1;}
